// player.js —— 第一人称玩家控制器
// 职责：PointerLock 鼠标视角、WASD 加速度移动、跳跃/重力、AABB 碰撞、血量护甲
// 采用 Source/CS 风格的速度向量积分（地面摩擦 + 空中受限控制）
// 经典脚本（非 ES Module）：THREE / CONFIG / clamp 由前置脚本挂到 window 提供

class Player {
  constructor(camera, gameMap, hud) {
    this.camera = camera;
    this.map = gameMap;
    this.hud = hud;
    const P = CONFIG.player;

    // 位置用 yaw/pitch 表示朝向，position 表示脚底
    this.position = new THREE.Vector3();
    this.velocity = new THREE.Vector3();
    this.yaw = 0;
    this.pitch = 0;
    this.onGround = true;

    // 状态
    this.health = P.maxHealth;
    this.armor = P.maxArmor;
    this.alive = true;
    this.crouching = false;

    // 输入
    this.keys = {};
    this._bindInput();

    // 视觉：手臂/枪模型挂在相机下，weapon 模块会注入
    this.recoilOffset = 0;     // 当前后坐力造成的视角上抬（用于恢复）
    this.viewBob = 0;          // 走路晃动相位
  }

  reset(spawn) {
    this.position.copy(spawn);
    this.velocity.set(0, 0, 0);
    this.yaw = 0; this.pitch = 0;
    this.onGround = true;
    this.health = CONFIG.player.maxHealth;
    this.armor = CONFIG.player.maxArmor;
    this.alive = true;
    this._syncCamera();
  }

  // ---------- 输入 ----------
  _bindInput() {
    this._onKeyDown = (e) => {
      this.keys[e.code] = true;
      // 防止 Space 滚动页面
      if (e.code === 'Space') e.preventDefault();
    };
    this._onKeyUp = (e) => { this.keys[e.code] = false; };
    window.addEventListener('keydown', this._onKeyDown);
    window.addEventListener('keyup', this._onKeyUp);
  }

  // 由 main 在 pointerlock 触发时调用
  onMouseMove(e) {
    if (!this.alive) return;
    const s = CONFIG.player.mouseSensitivity;
    this.yaw -= e.movementX * s;
    this.pitch -= e.movementY * s;
    this.pitch = clamp(this.pitch, -Math.PI / 2 + 0.01, Math.PI / 2 - 0.01);
  }

  // 触屏视角（灵敏度更高）
  onTouchLook(dx, dy) {
    if (!this.alive) return;
    const s = CONFIG.player.touchSensitivity;
    this.yaw -= dx * s;
    this.pitch -= dy * s;
    this.pitch = clamp(this.pitch, -Math.PI / 2 + 0.01, Math.PI / 2 - 0.01);
  }

  // ---------- 受伤 ----------
  takeDamage(amount) {
    if (!this.alive) return 0;
    let dmg = amount;
    // 护甲吸收 50%
    if (this.armor > 0) {
      const absorbed = Math.min(this.armor, dmg * 0.5);
      this.armor -= absorbed;
      dmg -= absorbed;
    }
    this.health -= dmg;
    this.hud.damageFlash();
    if (this.health <= 0) {
      this.health = 0;
      this.alive = false;
    }
    this.hud.updateVitals(this.health, this.armor);
    return dmg;
  }

  heal(amount) {
    this.health = clamp(this.health + amount, 0, CONFIG.player.maxHealth);
    this.hud.updateVitals(this.health, this.armor);
  }

  // ---------- 主更新 ----------
  update(dt) {
    if (!this.alive) return;

    const P = CONFIG.player;
    // ---- 朝向（yaw 绕 Y，pitch 绕 X）----
    // 后坐力上抬叠加在 pitch 上
    this._syncCamera();

    // ---- 输入方向（局部空间）----
    const fwd = (this.keys['KeyW'] ? 1 : 0) - (this.keys['KeyS'] ? 1 : 0);
    const right = (this.keys['KeyD'] ? 1 : 0) - (this.keys['KeyA'] ? 1 : 0);

    // 静步/蹲
    this.crouching = !!this.keys['ShiftLeft'] || !!this.keys['ControlLeft'];
    const wishSpeed = this.crouching ? P.crouchSpeed : P.walkSpeed;

    // 计算期望速度（基于 yaw，水平面）
    const sin = Math.sin(this.yaw), cos = Math.cos(this.yaw);
    // 相机 forward 在水平面：(-sin, 0, -cos)
    const wishX = (-sin * fwd + cos * right);
    const wishZ = (-cos * fwd - sin * right);
    const wishLen = Math.hypot(wishX, wishZ);
    const wishDirX = wishLen > 0 ? wishX / wishLen : 0;
    const wishDirZ = wishLen > 0 ? wishZ / wishLen : 0;
    const wishVelX = wishDirX * wishSpeed * (wishLen > 0 ? Math.min(wishLen, 1) : 0);
    const wishVelZ = wishDirZ * wishSpeed * (wishLen > 0 ? Math.min(wishLen, 1) : 0);

    // ---- 水平移动积分（CS 风格 accelerate + friction）----
    if (this.onGround) {
      // 摩擦：把当前水平速度向 0 衰减
      const speed = Math.hypot(this.velocity.x, this.velocity.z);
      if (speed > 0) {
        const drop = speed * P.friction * dt;
        const newSpeed = Math.max(0, speed - drop) / speed;
        this.velocity.x *= newSpeed;
        this.velocity.z *= newSpeed;
      }
      this._accelerate(wishDirX, wishDirZ, wishSpeed, P.accelGround, dt);
    } else {
      // 空中：受限加速（保留惯性）
      this._accelerate(wishDirX, wishDirZ, wishSpeed, P.accelAir, dt);
    }

    // ---- 跳跃 ----
    if (this.keys['Space'] && this.onGround) {
      this.velocity.y = P.jumpVelocity;
      this.onGround = false;
    }

    // ---- 重力 ----
    this.velocity.y -= P.gravity * dt;

    // ---- 位置积分 + 碰撞 ----
    // 先积分位置
    this.position.x += this.velocity.x * dt;
    this.position.z += this.velocity.z * dt;
    // XZ 碰撞解算
    const resolved = this.map.collide(this.position.x, this.position.z, P.radius);
    // 如果被推开，说明撞墙，清除该方向速度（简单处理）
    const pushX = resolved.x - this.position.x;
    const pushZ = resolved.z - this.position.z;
    if (Math.abs(pushX) > 0.001 || Math.abs(pushZ) > 0.001) {
      // 沿法线反弹掉该分量
      const nLen = Math.hypot(pushX, pushZ) || 1;
      const nx = pushX / nLen, nz = pushZ / nLen;
      const vDotN = this.velocity.x * nx + this.velocity.z * nz;
      if (vDotN < 0) {
        this.velocity.x -= vDotN * nx;
        this.velocity.z -= vDotN * nz;
      }
      this.position.x = resolved.x;
      this.position.z = resolved.z;
    }

    // Y 轴：地面 y=0
    this.position.y += this.velocity.y * dt;
    if (this.position.y <= 0) {
      this.position.y = 0;
      this.velocity.y = 0;
      this.onGround = true;
    }

    // ---- 视角晃动（走路 bob）----
    const hSpeed = Math.hypot(this.velocity.x, this.velocity.z);
    if (this.onGround && hSpeed > 0.5) {
      this.viewBob += dt * hSpeed * 1.4;
    } else {
      this.viewBob *= 0.9;
    }

    // ---- 后坐力恢复 ----
    if (this.recoilOffset > 0) {
      const recover = Math.min(this.recoilOffset, dt * 0.06);
      this.recoilOffset -= recover;
      this.pitch += recover;     // 恢复时 pitch 回正（注意 add）
    }

    this._syncCamera();
  }

  // 沿期望方向加速
  _accelerate(wishDirX, wishDirZ, wishSpeed, accel, dt) {
    const currentSpeed = this.velocity.x * wishDirX + this.velocity.z * wishDirZ;
    const addSpeed = wishSpeed - currentSpeed;
    if (addSpeed <= 0) return;
    let accelSpeed = accel * wishSpeed * dt;
    if (accelSpeed > addSpeed) accelSpeed = addSpeed;
    this.velocity.x += accelSpeed * wishDirX;
    this.velocity.z += accelSpeed * wishDirZ;
  }

  // 施加一发射击的后坐力
  applyRecoil(recoilDef) {
    this.pitch -= recoilDef.x;          // 上抬（pitch 减小=向上）
    this.recoilOffset += recoilDef.x;
    this.yaw += (Math.random() - 0.5) * 2 * recoilDef.y;
    this.pitch = clamp(this.pitch, -Math.PI / 2 + 0.01, Math.PI / 2 - 0.01);
  }

  _syncCamera() {
    const P = CONFIG.player;
    const bobY = Math.sin(this.viewBob * 2) * 0.04 * (this.onGround ? 1 : 0);
    const bobX = Math.cos(this.viewBob) * 0.03 * (this.onGround ? 1 : 0);
    this.camera.position.set(
      this.position.x + bobX * 0.3,
      this.position.y + P.height + bobY,
      this.position.z
    );
    // 用欧拉角 YXZ 避免万向锁
    this.camera.rotation.set(this.pitch, this.yaw, 0, 'YXZ');
  }

  // 提供给武器模块：相机朝向射线
  // 起点用"无走路晃动"的眼位（bob 只影响渲染位置），保证弹道与屏幕中心准星严格重合
  getAimRay() {
    const dir = new THREE.Vector3(0, 0, -1);
    dir.applyEuler(new THREE.Euler(this.pitch, this.yaw, 0, 'YXZ'));
    return {
      origin: new THREE.Vector3(this.position.x, this.position.y + CONFIG.player.height, this.position.z),
      direction: dir.normalize(),
    };
  }

  // 提供给敌人：脚底位置
  getFeet() { return this.position; }
  getEye() { return this.camera.position; }

  dispose() {
    window.removeEventListener('keydown', this._onKeyDown);
    window.removeEventListener('keyup', this._onKeyUp);
  }
}

// 经典脚本全局暴露（依赖顺序：config → three(UMD) → map → player → …）
window.Player = Player;
